"""Shared collection monitor for the Pi and the laptop's Pi section."""
from __future__ import annotations


def collection_page(*, remote: bool = False, initial_tab: str = "live") -> str:
    try:
        from .hub_dashboard import hub_page
    except ImportError:
        from hub_dashboard import hub_page
    return hub_page(COLLECTION_HTML, remote=remote, initial_tab=initial_tab)


COLLECTION_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bird collection · Pi monitor</title><style>
:root{color-scheme:light dark;--bg:#fafaf8;--ink:#17231e;--muted:#637169;--line:#d0d8d1;--panel:#fff;--accent:#19704d}
@media(prefers-color-scheme:dark){:root{--bg:#131b17;--ink:#e1ece4;--muted:#a0b1a6;--line:#394b40;--panel:#1c2921;--accent:#79d3a0}}
[hidden]{display:none!important}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,sans-serif}
header,main{max-width:1500px;margin:auto;padding:18px 24px}header{border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px;flex-wrap:wrap}
h1{font-size:20px;margin:0}h2{font-size:15px;margin:0 0 10px}a{color:var(--accent)}nav{margin-left:auto;display:flex;gap:18px}
button,input,select,textarea{font:inherit;padding:8px;border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:5px}button{cursor:pointer}button:hover{border-color:var(--accent)}button:disabled{opacity:.5;cursor:default}input{min-width:210px}textarea{width:100%;min-height:60px}
.toolbar,.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.toolbar{margin-bottom:16px}.muted,small{color:var(--muted)}#notice{color:var(--accent);min-height:24px}.error{color:#d45748!important}
.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:20px}.metric{border:1px solid var(--line);padding:12px;background:var(--panel)}.metric strong{display:block;font-size:23px}.metric span{font-size:12px;color:var(--muted)}
.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:22px}aside{min-width:0}.camera{display:block;width:100%;text-align:left;margin-bottom:8px}.camera.selected{border:2px solid var(--accent)}.camera strong,.camera small{display:block}.camera small{white-space:normal}
.work{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:18px}.preview{position:relative;background:#080b09;min-height:200px}.preview img{display:block;width:100%;height:auto}.preview svg{position:absolute;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.preview rect{fill:transparent;stroke:#75edaa;stroke-width:2;vector-effect:non-scaling-stroke}.preview rect.draft{stroke:#ffcf6c;stroke-dasharray:5 3}
.card{border:1px solid var(--line);padding:14px;background:var(--panel);min-width:0}#identity{overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;margin:10px 0}#crops{display:flex;gap:8px;flex-wrap:wrap}#crops figure{margin:0;max-width:150px}#crops img{max-width:140px;max-height:150px;background:#111}#crops figcaption{font-size:11px;color:var(--muted)}
.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:10px;margin-top:12px}.thumb{padding:0;text-align:left;overflow:hidden}.thumb img{display:block;width:100%;aspect-ratio:4/3;object-fit:contain;background:#111}.thumb span{display:block;font-size:11px;padding:5px}.thumb.selected{border:2px solid var(--accent)}.box-row{font-size:12px;margin:4px 0;display:flex;justify-content:space-between;gap:8px}.box-row button{padding:1px 7px}.section{margin-top:22px}pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}
@media(max-width:950px){.layout,.work{grid-template-columns:1fr}aside{display:flex;gap:8px;flex-wrap:wrap}.camera{width:auto;flex:1 1 180px}header,main{padding:14px}}
</style></head><body><header><div><h1>Bird collection</h1><small>Original frames · candidate crops · human review</small></div><nav><a href="/">Overview</a><a href="/fleet">Camera fleet</a><a id="legacy" href="/legacy">Camera settings</a></nav></header>
<main><form id="connect" class="toolbar" hidden><label>Pi URL <input id="pi-url" type="url" placeholder="http://192.168.7.128:5000" required></label><button>Connect Pi</button><span class="muted">Saved on this laptop. Cameras remain connected to the Pi.</span></form>
<div class="toolbar"><button id="refresh">Refresh</button><label><input id="auto" type="checkbox" checked style="min-width:0"> Auto refresh</label><span id="connection" class="muted">Connecting…</span></div><div id="notice" role="status"></div>
<div class="metrics" id="metrics"></div><div class="layout"><aside id="cameras"></aside><section><div class="work"><div><div class="preview"><img id="image" alt="Select a saved frame"><svg id="overlay" aria-label="Bird box editor"></svg></div><div id="identity">No saved frame selected.</div><div class="actions"><button id="clear-boxes">Clear boxes</button><button id="restore-boxes">Use predicted boxes</button><span class="muted">Drag on the image to draw tight boxes around every visible bird.</span></div><div id="boxes"></div></div>
<div class="card"><h2>Review original frame</h2><p class="muted">Predictions are candidates. Confirm empty scenes too, including false triggers. Check the entire frame before marking it empty.</p><div class="actions"><button data-review="boxed">Confirm bird boxes</button><button data-review="no_bird">Confirm empty</button><button data-review="unusable">Unusable</button><button data-review="unreviewed">Undo review</button></div><p><label>Species for all boxes, if the same <input id="species" placeholder="Leave blank if unknown"></label></p><textarea id="note" placeholder="Scene, visibility, or review note"></textarea><p id="review-state" class="muted">Unreviewed</p><h2>Candidate crops</h2><div id="crops"></div><p class="muted">Native-size PNG crops, no stretch or padding. Confirming empty never deletes the original or model evidence.</p></div></div>
<div class="section"><div class="toolbar"><h2>Saved frames</h2><select id="filter"><option value="all">All frames</option><option value="unreviewed">Unreviewed</option><option value="no_bird">Confirmed empty</option><option value="boxed">Confirmed bird boxes</option><option value="unusable">Unusable</option></select><button id="older">Older frames</button><button id="newest">Newest frames</button><a id="export" href="#">Export dataset CSV</a></div><small>Showing up to 30 frames per page. Review filters apply to this page. Full originals remain on the Pi.</small><div id="gallery" class="gallery"></div></div><details class="section"><summary>Diagnostics</summary><pre id="diagnostics"></pre></details></section></div></main>
<script>
const REMOTE=__REMOTE__, $=id=>document.getElementById(id), S={health:null,camera:'',captures:[],selected:null,boxes:[],before:'',next:null,loading:false,dirty:false};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const endpoint=p=>REMOTE?(p.startsWith('/api/pi/')?p:p==='/health'?'/api/pi/health':p.replace(/^\/api\//,'/api/pi/')):p;
const api=async(p,options)=>{const r=await fetch(endpoint(p),{cache:'no-store',...options});const j=await r.json().catch(()=>({error:`Hub HTTP ${r.status}`}));if(!r.ok)throw Error(j.error||`HTTP ${r.status}`);return j};
function message(s,error=false){$('notice').textContent=s;$('notice').className=error?'error':''}
const review=c=>c?.review?.decision||'unreviewed';
function metric(label,value){return `<div class="metric"><strong>${esc(value)}</strong><span>${esc(label)}</span></div>`}
function renderHealth(){const h=S.health,services=h.motion_services||{},values=Object.values(services);const failures=values.reduce((n,s)=>n+(s.failures||0),0),frames=values.reduce((n,s)=>n+(h.collection_mode?s.frames_captured||0:s.frames_polled||0),0),skipped=values.reduce((n,s)=>n+(s.inference_skipped||0),0);$('metrics').innerHTML=metric('Collection mode',h.collection_mode?'ON · species off':'OFF')+metric('Captured originals',frames)+metric('Capture failures',failures)+metric('Analysis skipped · originals kept',skipped)+metric('Free storage',h.storage_free_bytes==null?'–':(h.storage_free_bytes/1073741824).toFixed(1)+' GB');
$('connection').textContent=`Updated ${new Date().toLocaleTimeString()} · ${(h.models||{}).detector?'Detector loaded':'Detector unavailable'}`;
$('cameras').innerHTML=(h.cameras||[]).map(c=>{const s=services[c.id]||{},t=s.last_inference?.timing_ms;return `<button class="camera ${S.camera===c.id?'selected':''}" data-camera="${esc(c.id)}"><strong>${esc(c.name)}</strong><small>${esc(c.url)} · ${s.running?'polling':'stopped'}</small><small>${s.frames_captured||s.frames_polled||0} captured · ${s.frames_polled||0} processed · ${s.failures||0} errors · background ${s.background_ready?'ready':'warming'}</small><small>${t?`${(t.total/1000).toFixed(2)}s processing`:''} ${esc(s.last_capture_error||s.last_analysis_error||s.last_error||'')}</small></button>`}).join('');
$('diagnostics').textContent=JSON.stringify({collection_mode:h.collection_mode,motion_services:services,models:h.models,save_dir:h.save_dir},null,2)}
function predicted(c){const i=c?.inference||{},threshold=i.detector?.threshold??.5;return(i.detector?.detections||[]).filter(d=>d.score>=threshold).map(d=>({...d.box}))}
function renderBoxes(){const img=$('image');$('overlay').setAttribute('viewBox',`0 0 ${img.naturalWidth||640} ${img.naturalHeight||480}`);$('overlay').innerHTML=S.boxes.map(b=>`<rect x="${b.left}" y="${b.top}" width="${b.right-b.left}" height="${b.bottom-b.top}"/>`).join('');$('boxes').innerHTML=S.boxes.map((b,n)=>`<div class="box-row"><span>Bird ${n+1}: ${Math.round(b.left)}, ${Math.round(b.top)} → ${Math.round(b.right)}, ${Math.round(b.bottom)}</span><button data-remove="${n}" aria-label="Remove bird box ${n+1}">×</button></div>`).join('')}
function choose(id){if(S.dirty&&!confirm('Discard unsaved box or note edits?'))return;const c=S.captures.find(x=>x.capture_id===id);if(!c)return;S.selected=c;S.dirty=false;S.boxes=c.review?.decision==='boxed'?(c.review.boxes||[]).map(b=>({...b})):predicted(c);$('image').src=endpoint(`/api/captures/${encodeURIComponent(id)}/image`);$('identity').textContent=`${c.camera_name||c.camera_id||'Camera'} · ${new Date(c.received_at).toLocaleString()}\n${id} · detector ${c.inference?.bird_probability?.toFixed(3)??'pending'}`;$('review-state').textContent=`Review: ${review(c)} · original and predictions preserved`;$('note').value=c.review?.note||'';$('species').value=c.review?.species_name||'';const reviewed=c.review?.decision==='boxed';const crops=(reviewed?c.review?.collection:c.inference?.collection)?.crops||[];$('crops').innerHTML=crops.length?crops.map(x=>`<figure><a href="${endpoint(`/api/captures/${encodeURIComponent(id)}/${reviewed?'review-crops':'crops'}/${x.detection_index}/image`)}" target="_blank" rel="noopener"><img src="${endpoint(`/api/captures/${encodeURIComponent(id)}/${reviewed?'review-crops':'crops'}/${x.detection_index}/image`)}" alt="Candidate bird crop"></a><figcaption>${x.width} × ${x.height} · ${reviewed?'human reviewed':'score '+x.score.toFixed(3)}</figcaption></figure>`).join(''):'<span class="muted">No candidate crops for this frame.</span>';renderBoxes();renderGallery()}
function renderGallery(){const f=$('filter').value;$('gallery').innerHTML=S.captures.filter(c=>f==='all'||review(c)===f).map(c=>`<button class="thumb ${S.selected?.capture_id===c.capture_id?'selected':''}" data-capture="${esc(c.capture_id)}"><img loading="lazy" src="${endpoint(`/api/captures/${encodeURIComponent(c.capture_id)}/image`)}" alt="Saved frame"><span>${esc(new Date(c.received_at).toLocaleTimeString())} · ${esc(review(c))}<br>${esc(c.camera_name||'')} · score ${c.inference?.bird_probability?.toFixed(2)??c.inference_status??'pending'}</span></button>`).join('')||'<p class="muted">No frames match on this page.</p>'}
async function refresh(){if(S.loading)return;S.loading=true;try{S.health=await api('/health');renderHealth();const q=new URLSearchParams({limit:'30',order:'desc'});if(S.camera)q.set('camera_registry_id',S.camera);if(S.before)q.set('before',S.before);const listing=await api('/api/captures?'+q);S.captures=listing.captures||[];S.next=listing.has_more?listing.next_before:null;$('older').disabled=!S.next;const updated=S.captures.find(c=>c.capture_id===S.selected?.capture_id);if(updated&&!S.dirty&&JSON.stringify(updated)!==JSON.stringify(S.selected))choose(updated.capture_id);renderGallery();if(!S.selected&&S.captures.length)choose(S.captures[0].capture_id);message(S.health.collection_mode?'Collection captures independently of inference and keeps originals, including empty and uncertain scenes.':'Collection mode is OFF. Enable --collection-mode on the Pi to retain empty scenes and export crops.');}catch(e){message(e.message,true);$('connection').textContent='Pi not connected or unavailable'}finally{S.loading=false}}
$('image').onload=renderBoxes;$('image').onerror=()=>message('Could not load the saved image. Refresh to retry.',true);
$('refresh').onclick=refresh;$('filter').onchange=renderGallery;$('older').onclick=()=>{if(S.dirty)return message('Save or undo your edits before changing pages.',true);S.before=S.next||'';S.selected=null;refresh()};$('newest').onclick=()=>{if(S.dirty)return message('Save or undo your edits before changing pages.',true);S.before='';S.selected=null;refresh()};
$('clear-boxes').onclick=()=>{S.boxes=[];S.dirty=true;renderBoxes()};$('restore-boxes').onclick=()=>{S.boxes=predicted(S.selected);S.dirty=true;renderBoxes()};$('note').oninput=$('species').oninput=()=>S.dirty=true;
document.addEventListener('click',async e=>{const cam=e.target.closest('[data-camera]'),capture=e.target.closest('[data-capture]'),remove=e.target.closest('[data-remove]'),button=e.target.closest('[data-review]');if(cam){if(S.dirty)return message('Save or undo edits before switching cameras.',true);S.camera=S.camera===cam.dataset.camera?'':cam.dataset.camera;S.before='';S.selected=null;refresh()}if(capture)choose(capture.dataset.capture);if(remove){S.boxes.splice(Number(remove.dataset.remove),1);S.dirty=true;renderBoxes()}if(button&&S.selected){const decision=button.dataset.review;if(decision==='boxed'&&!S.boxes.length)return message('Draw at least one bird box first.',true);if(decision==='no_bird'&&!confirm('Confirm the entire original frame contains no birds, including partially hidden birds?'))return;button.disabled=true;try{const r=await api(`/api/captures/${encodeURIComponent(S.selected.capture_id)}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,boxes:decision==='boxed'?S.boxes:[],note:$('note').value,species_name:decision==='boxed'?$('species').value.trim():null})});S.selected.review=r;S.dirty=false;choose(S.selected.capture_id);$('review-state').textContent=`Review: ${r.decision} · saved`;renderGallery();message('Review saved. Predictions and original metadata are unchanged.')}catch(e){message(e.message,true)}finally{button.disabled=false}}});
function point(e){const r=$('overlay').getBoundingClientRect(),im=$('image');return{x:Math.max(0,Math.min(im.naturalWidth,(e.clientX-r.left)/r.width*im.naturalWidth)),y:Math.max(0,Math.min(im.naturalHeight,(e.clientY-r.top)/r.height*im.naturalHeight))}}
let start=null;$('overlay').onpointerdown=e=>{if(!S.selected||!$('image').naturalWidth||e.button!==0)return;start=point(e);$('overlay').setPointerCapture(e.pointerId);e.preventDefault()};$('overlay').onpointermove=e=>{if(!start)return;renderBoxes();const p=point(e),r=document.createElementNS('http://www.w3.org/2000/svg','rect');r.setAttribute('class','draft');for(const[k,v]of Object.entries({x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),width:Math.abs(p.x-start.x),height:Math.abs(p.y-start.y)}))r.setAttribute(k,v);$('overlay').append(r)};$('overlay').onpointerup=e=>{if(!start)return;const p=point(e);if(Math.abs(p.x-start.x)>=2&&Math.abs(p.y-start.y)>=2){S.boxes.push({left:Math.min(start.x,p.x),top:Math.min(start.y,p.y),right:Math.max(start.x,p.x),bottom:Math.max(start.y,p.y)});S.dirty=true}start=null;renderBoxes()};$('overlay').onpointercancel=()=>{start=null;renderBoxes()};
$('export').href=endpoint('/api/collection/export.csv');
let lastTimeOffer=0;function offerTime(){if(Date.now()-lastTimeOffer<300000)return;lastTimeOffer=Date.now();api('/api/time',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_unix_ms:Date.now()})}).catch(()=>{})}
async function init(){offerTime();if(REMOTE){$('connect').hidden=false;$('legacy').hidden=true;try{const c=await api('/api/pi/config');$('pi-url').value=c.pi_url||''}catch(e){message(e.message,true)}}await refresh()}
$('connect').onsubmit=async e=>{e.preventDefault();try{const r=await fetch('/api/pi/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pi_url:$('pi-url').value})});const b=await r.json();if(!r.ok)throw Error(b.error);S.selected=null;S.before='';lastTimeOffer=0;offerTime();await refresh()}catch(e){message(e.message,true)}};
init();setInterval(()=>{offerTime();if($('auto').checked&&!S.dirty)refresh()},5000);
</script></body></html>'''
